-- Communications E1 (docs/communications-e1.md): retention and erasure foundation. The erasure ledger
-- (communications_erasures, communications_erasure_items), legal holds, keyed erased references, single-use
-- privileged grants, the per-copy retention category on messages, erasure markers on C1 rows, the 30-day
-- delay on shortening the ordinary retention period, and the guard changes that let ONLY the erasure
-- pathway (bos_maint functions in prisma/privileged/004_communications_erasure.sql) remove content.
-- Generated by `prisma migrate diff`, then the constraints, guards, grants and RLS Prisma cannot express were
-- added by hand (sections marked "hand-written"). One transaction (docs/migration-readiness.md §7).
--
-- Ordering: depends on 20261119300000_communications (conversations, messages, participants, activity
-- links), 20261121000000_communications_providers and 20261125000000_communications_mailbox_identity
-- (mail_connections, mail_retention_settings) and 20261113150000_tenancy (audit_events). It references no
-- finance, people, scheduling or reporting object, so it commutes with Scheduling S2
-- (20261128000000_scheduling_resources); its name sorts after that and after every migration on main.
-- Additive: new nullable columns and new tables; relaxed CHECKs that still hold for every existing row;
-- replaced guard functions that behave exactly as before for every role except bos_maint. No row changes.
-- No content is deleted by this migration and nothing is scheduled.
BEGIN;
-- AlterTable
ALTER TABLE "activities" ADD COLUMN     "erased_at" TIMESTAMPTZ;

-- AlterTable
ALTER TABLE "conversations" ADD COLUMN     "erased_at" TIMESTAMPTZ;

-- AlterTable
ALTER TABLE "mail_retention_settings" ADD COLUMN     "previous_retention_days" INTEGER,
ADD COLUMN     "shortening_effective_at" TIMESTAMPTZ;

-- AlterTable
ALTER TABLE "message_participants" ADD COLUMN     "erased_at" TIMESTAMPTZ;

-- AlterTable
ALTER TABLE "messages" ADD COLUMN     "erased_at" TIMESTAMPTZ,
ADD COLUMN     "retention_category" TEXT;

-- CreateTable
CREATE TABLE "communications_erasures" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "kind" TEXT NOT NULL,
    "target_type" TEXT,
    "contact_id" UUID,
    "conversation_id" UUID,
    "message_id" UUID,
    "reason_code" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'PENDING',
    "requested_by_id" UUID,
    "requested_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "next_attempt_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "last_error_code" TEXT,
    "deferred_reason" TEXT,
    "messages_erased" INTEGER NOT NULL DEFAULT 0,
    "participants_erased" INTEGER NOT NULL DEFAULT 0,
    "activities_erased" INTEGER NOT NULL DEFAULT 0,
    "conversations_erased" INTEGER NOT NULL DEFAULT 0,
    "review_required" INTEGER NOT NULL DEFAULT 0,
    "deferred_count" INTEGER NOT NULL DEFAULT 0,
    "completed_at" TIMESTAMPTZ,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "communications_erasures_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateTable
CREATE TABLE "communications_erasure_items" (
    "business_id" UUID NOT NULL,
    "erasure_id" UUID NOT NULL,
    "entity_type" TEXT NOT NULL,
    "entity_id" UUID NOT NULL,
    "action" TEXT NOT NULL,
    "recorded_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "communications_erasure_items_pkey" PRIMARY KEY ("business_id","erasure_id","entity_type","entity_id")
);

-- CreateTable
CREATE TABLE "communications_legal_holds" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "scope" TEXT NOT NULL,
    "contact_id" UUID,
    "connection_id" UUID,
    "reason_code" TEXT NOT NULL,
    "placed_by_id" UUID NOT NULL,
    "placed_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "released_at" TIMESTAMPTZ,
    "released_by_id" UUID,

    CONSTRAINT "communications_legal_holds_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateTable
CREATE TABLE "communications_erasure_keys" (
    "business_id" UUID NOT NULL,
    "secret" BYTEA NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "communications_erasure_keys_pkey" PRIMARY KEY ("business_id")
);

-- CreateTable
CREATE TABLE "communications_erased_references" (
    "business_id" UUID NOT NULL,
    "kind" TEXT NOT NULL,
    "digest" CHAR(64) NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expires_at" TIMESTAMPTZ NOT NULL,

    CONSTRAINT "communications_erased_references_pkey" PRIMARY KEY ("business_id","kind","digest")
);

-- CreateTable
CREATE TABLE "communications_privileged_grants" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "operation" TEXT NOT NULL,
    "target_id" UUID,
    "code_hash" CHAR(64) NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expires_at" TIMESTAMPTZ NOT NULL,
    "consumed_at" TIMESTAMPTZ,

    CONSTRAINT "communications_privileged_grants_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateIndex
CREATE INDEX "communications_erasures_business_id_status_next_attempt_at_idx" ON "communications_erasures"("business_id", "status", "next_attempt_at");

-- CreateIndex
CREATE INDEX "communications_erasures_business_id_requested_at_id_idx" ON "communications_erasures"("business_id", "requested_at" DESC, "id");

-- CreateIndex
CREATE INDEX "communications_erasure_items_business_id_entity_type_entity_idx" ON "communications_erasure_items"("business_id", "entity_type", "entity_id");

-- CreateIndex
CREATE INDEX "communications_legal_holds_business_id_placed_at_id_idx" ON "communications_legal_holds"("business_id", "placed_at" DESC, "id");

-- CreateIndex
CREATE INDEX "communications_erased_references_expires_at_idx" ON "communications_erased_references"("expires_at");

-- CreateIndex
CREATE UNIQUE INDEX "communications_privileged_grants_code_hash_key" ON "communications_privileged_grants"("code_hash");

-- AddForeignKey
ALTER TABLE "communications_erasures" ADD CONSTRAINT "communications_erasures_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "communications_erasures" ADD CONSTRAINT "communications_erasures_contact_fkey" FOREIGN KEY ("business_id", "contact_id") REFERENCES "contacts"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "communications_erasures" ADD CONSTRAINT "communications_erasures_conversation_fkey" FOREIGN KEY ("business_id", "conversation_id") REFERENCES "conversations"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "communications_erasures" ADD CONSTRAINT "communications_erasures_message_fkey" FOREIGN KEY ("business_id", "message_id") REFERENCES "messages"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "communications_erasure_items" ADD CONSTRAINT "communications_erasure_items_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "communications_erasure_items" ADD CONSTRAINT "communications_erasure_items_erasure_fkey" FOREIGN KEY ("business_id", "erasure_id") REFERENCES "communications_erasures"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "communications_legal_holds" ADD CONSTRAINT "communications_legal_holds_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "communications_legal_holds" ADD CONSTRAINT "communications_legal_holds_contact_fkey" FOREIGN KEY ("business_id", "contact_id") REFERENCES "contacts"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "communications_legal_holds" ADD CONSTRAINT "communications_legal_holds_connection_fkey" FOREIGN KEY ("business_id", "connection_id") REFERENCES "mail_connections"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "communications_erasure_keys" ADD CONSTRAINT "communications_erasure_keys_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "communications_erased_references" ADD CONSTRAINT "communications_erased_references_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "communications_privileged_grants" ADD CONSTRAINT "communications_privileged_grants_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;



-- =============================================================================================
-- Hand-written: constraints, guards, helper functions, grants and RLS.
-- New SQLSTATEs: CM011 erased (no new content attaches to an erased conversation or message),
-- CM012 legal hold rule, CM013 erasure ledger is append-only / fixed.
-- The name bos_maint below is the no-login role that owns the erasure functions
-- (prisma/privileged/004_communications_erasure.sql). No login role is a member of it
-- (schema test checks pg_auth_members), so no application SQL can run as it.
-- =============================================================================================

-- ---- erasure markers on C1 rows ----------------------------------------------------------------
-- An erased row keeps its id, links, direction and time (thread and timeline structure, D-E1-2) and holds no
-- personal content: the erased-empty CHECKs make "marked erased but content kept" impossible for every role.
ALTER TABLE "messages" DROP CONSTRAINT messages_has_content,
  ADD CONSTRAINT messages_has_content CHECK ("subject" IS NOT NULL OR "body" IS NOT NULL OR "erased_at" IS NOT NULL),
  DROP CONSTRAINT messages_import_has_external_id,
  ADD CONSTRAINT messages_import_has_external_id CHECK ("source" <> 'IMPORT' OR "external_message_id" IS NOT NULL OR "erased_at" IS NOT NULL),
  ADD CONSTRAINT messages_retention_category_values CHECK (
    "retention_category" IS NULL OR "retention_category" IN ('PERSONAL_UNSHARED', 'ORDINARY', 'RETAINED_RECORD', 'STAGED_INTAKE')),
  ADD CONSTRAINT messages_erased_empty CHECK (
    "erased_at" IS NULL OR ("subject" IS NULL AND "body" IS NULL AND "external_source" IS NULL AND "external_message_id" IS NULL));
ALTER TABLE "message_participants" DROP CONSTRAINT message_participants_identified,
  ADD CONSTRAINT message_participants_identified CHECK (
    "display_name" IS NOT NULL OR "address" IS NOT NULL OR "contact_id" IS NOT NULL OR "user_id" IS NOT NULL OR "erased_at" IS NOT NULL),
  ADD CONSTRAINT message_participants_erased_empty CHECK ("erased_at" IS NULL OR ("display_name" IS NULL AND "address" IS NULL AND "contact_id" IS NULL));
ALTER TABLE "conversations"
  ADD CONSTRAINT conversations_erased_empty CHECK ("erased_at" IS NULL OR ("subject" IS NULL AND "external_thread_id" IS NULL));
ALTER TABLE "activities"
  ADD CONSTRAINT activities_erased_empty CHECK ("erased_at" IS NULL OR ("subject" IS NULL AND "body" IS NULL));
-- Retention purge finds live categorised copies without scanning C1 history.
CREATE INDEX "messages_retention_live_idx" ON "messages" ("business_id", "retention_category", "occurred_at", "id")
  WHERE "erased_at" IS NULL AND "retention_category" IS NOT NULL;

-- Message history stays read-only (CM002) for every role except bos_maint, which may only turn a row into an
-- erasure tombstone, once: content and provider identifiers to null, erased_at set, nothing else changed.
CREATE OR REPLACE FUNCTION communications_read_only() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF current_user = 'bos_maint' THEN
    IF TG_TABLE_NAME = 'messages' THEN
      IF (NEW.id, NEW.business_id, NEW.conversation_id, NEW.direction, NEW.source, NEW.occurred_at, NEW.recorded_at, NEW.recorded_by_id,
          NEW.retention_category)
         IS DISTINCT FROM
         (OLD.id, OLD.business_id, OLD.conversation_id, OLD.direction, OLD.source, OLD.occurred_at, OLD.recorded_at, OLD.recorded_by_id,
          OLD.retention_category)
         OR OLD.erased_at IS NOT NULL OR NEW.erased_at IS NULL
         OR NEW.subject IS NOT NULL OR NEW.body IS NOT NULL OR NEW.external_source IS NOT NULL OR NEW.external_message_id IS NOT NULL THEN
        RAISE EXCEPTION 'message history is read-only' USING ERRCODE = 'CM002';
      END IF;
      RETURN NEW;
    ELSIF TG_TABLE_NAME = 'message_participants' THEN
      -- Erasing a participant removes its name, address and contact link; the member link (user_id) stays.
      IF (NEW.id, NEW.business_id, NEW.message_id, NEW.role, NEW.position, NEW.user_id)
         IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.message_id, OLD.role, OLD.position, OLD.user_id)
         OR OLD.erased_at IS NOT NULL OR NEW.erased_at IS NULL OR NEW.display_name IS NOT NULL OR NEW.address IS NOT NULL
         OR NEW.contact_id IS NOT NULL THEN
        RAISE EXCEPTION 'message history is read-only' USING ERRCODE = 'CM002';
      END IF;
      RETURN NEW;
    END IF;
  END IF;
  RAISE EXCEPTION 'message history is read-only' USING ERRCODE = 'CM002';
END $$;

-- No new content attaches to erased history (CM011). The conversation row is read FOR KEY SHARE: an erasure
-- holds it FOR UPDATE while it works, so a racing insert waits and then sees erased_at (docs/communications-e1.md §9).
CREATE FUNCTION messages_guard_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  v_erased timestamptz;
BEGIN
  IF NEW.erased_at IS NOT NULL THEN
    RAISE EXCEPTION 'a message cannot be recorded as erased' USING ERRCODE = 'CM011';
  END IF;
  IF NEW.retention_category IS NOT NULL AND current_user = 'bos_app' THEN
    RAISE EXCEPTION 'retention categories are set by the mailbox sync (C2-B3), not by the application' USING ERRCODE = 'CM011';
  END IF;
  -- Lock the conversation row whatever its state: an erasure step holds it FOR UPDATE, so this waits for that
  -- step and then reads the committed row (READ COMMITTED re-check). Filtering on erased_at before locking
  -- would skip the row and let a message into a conversation erased a moment later.
  SELECT c."erased_at" INTO v_erased FROM "conversations" c
   WHERE c."business_id" = NEW.business_id AND c."id" = NEW.conversation_id
   FOR KEY SHARE;
  IF v_erased IS NOT NULL THEN
    RAISE EXCEPTION 'this conversation was erased' USING ERRCODE = 'CM011';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER messages_guard_insert BEFORE INSERT ON "messages" FOR EACH ROW EXECUTE FUNCTION messages_guard_insert();

CREATE FUNCTION message_participants_guard_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  v_erased timestamptz;
  v_same_tx boolean;
BEGIN
  IF NEW.erased_at IS NOT NULL THEN
    RAISE EXCEPTION 'a participant cannot be recorded as erased' USING ERRCODE = 'CM011';
  END IF;
  -- A participant is written in the same transaction as its message, never later (C1 and every importer do
  -- this). Enforcing that closes the race with an erasure step without needing a row lock that bos_app has
  -- no right to take on messages: a message from an earlier transaction, erased or not, takes no new
  -- participants. A message this tenant cannot see is left to the foreign key (same answer as before).
  SELECT m."erased_at", m.xmin = pg_catalog.pg_current_xact_id()::xid INTO v_erased, v_same_tx FROM "messages" m
   WHERE m."business_id" = NEW.business_id AND m."id" = NEW.message_id;
  IF FOUND AND (v_erased IS NOT NULL OR NOT v_same_tx) THEN
    RAISE EXCEPTION 'participants are recorded with their message' USING ERRCODE = 'CM011';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER message_participants_guard_insert BEFORE INSERT ON "message_participants" FOR EACH ROW EXECUTE FUNCTION message_participants_guard_insert();

-- conversations: as in C1, plus the bos_maint erasure branch (subject and external thread id to null, once).
CREATE OR REPLACE FUNCTION conversations_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF current_user = 'bos_maint' THEN
    IF (NEW.id, NEW.business_id, NEW.channel, NEW.customer_id, NEW.contact_id, NEW.source, NEW.created_by_id, NEW.created_at, NEW.last_message_at)
       IS DISTINCT FROM
       (OLD.id, OLD.business_id, OLD.channel, OLD.customer_id, OLD.contact_id, OLD.source, OLD.created_by_id, OLD.created_at, OLD.last_message_at)
       OR OLD.erased_at IS NOT NULL OR NEW.erased_at IS NULL
       OR NEW.subject IS NOT NULL OR NEW.external_source IS NOT NULL OR NEW.external_thread_id IS NOT NULL THEN
      RAISE EXCEPTION 'conversation identity is fixed' USING ERRCODE = 'CM001';
    END IF;
    RETURN NEW;
  END IF;
  IF (NEW.id, NEW.business_id, NEW.channel, NEW.subject, NEW.customer_id, NEW.contact_id, NEW.source, NEW.external_source,
      NEW.external_thread_id, NEW.created_by_id, NEW.created_at, NEW.erased_at)
     IS DISTINCT FROM
     (OLD.id, OLD.business_id, OLD.channel, OLD.subject, OLD.customer_id, OLD.contact_id, OLD.source, OLD.external_source,
      OLD.external_thread_id, OLD.created_by_id, OLD.created_at, OLD.erased_at) THEN
    RAISE EXCEPTION 'conversation identity is fixed' USING ERRCODE = 'CM001';
  END IF;
  -- last_message_at only moves forward (C1-01).
  IF OLD.last_message_at IS NOT NULL AND (NEW.last_message_at IS NULL OR NEW.last_message_at < OLD.last_message_at) THEN
    NEW.last_message_at := OLD.last_message_at;
  END IF;
  RETURN NEW;
END $$;

-- activities: as in C1, plus (1) the bos_maint erasure branch (subject and body to null, once, any user-entered
-- or removed entry) and (2) an erased entry is final for everyone else (no edit, no removal brings text back).
CREATE OR REPLACE FUNCTION activities_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF current_user = 'bos_maint' THEN
    IF (NEW.id, NEW.business_id, NEW.type, NEW.occurred_at, NEW.actor_type, NEW.actor_user_id, NEW.customer_id, NEW.contact_id,
        NEW.data, NEW.schema_version, NEW.created_at, NEW.visibility, NEW.conversation_id, NEW.message_id, NEW.deleted_at, NEW.edited_at)
       IS DISTINCT FROM
       (OLD.id, OLD.business_id, OLD.type, OLD.occurred_at, OLD.actor_type, OLD.actor_user_id, OLD.customer_id, OLD.contact_id,
        OLD.data, OLD.schema_version, OLD.created_at, OLD.visibility, OLD.conversation_id, OLD.message_id, OLD.deleted_at, OLD.edited_at)
       OR OLD.erased_at IS NOT NULL OR NEW.erased_at IS NULL OR NEW.subject IS NOT NULL OR NEW.body IS NOT NULL THEN
      RAISE EXCEPTION 'activity identity is fixed' USING ERRCODE = 'CM001';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.erased_at IS NOT NULL OR NEW.erased_at IS NOT NULL THEN
    RAISE EXCEPTION 'erased activities are final' USING ERRCODE = 'CM001';
  END IF;
  IF (NEW.id, NEW.business_id, NEW.type, NEW.occurred_at, NEW.actor_type, NEW.actor_user_id, NEW.customer_id, NEW.contact_id,
      NEW.data, NEW.schema_version, NEW.created_at, NEW.visibility, NEW.conversation_id, NEW.message_id)
     IS DISTINCT FROM
     (OLD.id, OLD.business_id, OLD.type, OLD.occurred_at, OLD.actor_type, OLD.actor_user_id, OLD.customer_id, OLD.contact_id,
      OLD.data, OLD.schema_version, OLD.created_at, OLD.visibility, OLD.conversation_id, OLD.message_id) THEN
    RAISE EXCEPTION 'activity identity is fixed' USING ERRCODE = 'CM001';
  END IF;
  IF OLD.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'removed activities are final' USING ERRCODE = 'CM001';
  END IF;
  IF NEW.deleted_at IS NOT NULL THEN
    IF position('.' in OLD.type) > 0 THEN
      RAISE EXCEPTION 'system activities cannot be removed' USING ERRCODE = 'CM003';
    END IF;
    IF (NEW.subject, NEW.body) IS DISTINCT FROM (OLD.subject, OLD.body) THEN
      RAISE EXCEPTION 'removal changes nothing else' USING ERRCODE = 'CM001';
    END IF;
    NEW.edited_at := OLD.edited_at;
    RETURN NEW;
  END IF;
  IF (NEW.subject, NEW.body) IS DISTINCT FROM (OLD.subject, OLD.body) THEN
    IF OLD.type <> 'note' THEN
      RAISE EXCEPTION 'only notes can be edited' USING ERRCODE = 'CM001';
    END IF;
    NEW.edited_at := now();
  ELSE
    NEW.edited_at := OLD.edited_at;
  END IF;
  RETURN NEW;
END $$;

-- ---- ordinary retention: shortening waits 30 days (D-E1-3) ------------------------------------------
-- Lengthening (or returning to at least the period in force) applies at once. Shortening keeps the period in
-- force for 30 more days: previous_retention_days and shortening_effective_at are stamped here on database
-- time, for every role, so no application path can make a reduction apply sooner. The only exception is
-- bos_maint (an OWNER-authorised, single-use, audited override, 004): it may clear the pending delay.
ALTER TABLE "mail_retention_settings"
  ADD CONSTRAINT mail_retention_settings_shortening_pair CHECK (("previous_retention_days" IS NULL) = ("shortening_effective_at" IS NULL)),
  ADD CONSTRAINT mail_retention_settings_shortening_longer CHECK ("previous_retention_days" IS NULL OR "previous_retention_days" > "ordinary_retention_days");

CREATE FUNCTION mail_effective_ordinary_days(p_days integer, p_previous integer, p_effective_at timestamptz) RETURNS integer
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog AS $$
  SELECT CASE WHEN p_effective_at IS NOT NULL AND p_effective_at > now() THEN greatest(p_days, p_previous) ELSE p_days END
$$;

CREATE FUNCTION mail_retention_settings_stamp() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  v_in_force integer;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.previous_retention_days := NULL;
    NEW.shortening_effective_at := NULL;
    RETURN NEW;
  END IF;
  IF current_user = 'bos_maint' THEN
    IF (NEW.business_id, NEW.ordinary_retention_days, NEW.updated_by_id, NEW.version, NEW.created_at)
       IS DISTINCT FROM (OLD.business_id, OLD.ordinary_retention_days, OLD.updated_by_id, OLD.version, OLD.created_at)
       OR NEW.previous_retention_days IS NOT NULL OR NEW.shortening_effective_at IS NOT NULL THEN
      RAISE EXCEPTION 'only a pending reduction can be applied early' USING ERRCODE = 'CM009';
    END IF;
    RETURN NEW;
  END IF;
  v_in_force := mail_effective_ordinary_days(OLD.ordinary_retention_days, OLD.previous_retention_days, OLD.shortening_effective_at);
  IF NEW.ordinary_retention_days < v_in_force THEN
    NEW.previous_retention_days := v_in_force;
    NEW.shortening_effective_at := now() + interval '30 days';
  ELSE
    NEW.previous_retention_days := NULL;
    NEW.shortening_effective_at := NULL;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_retention_settings_stamp BEFORE INSERT OR UPDATE ON "mail_retention_settings"
  FOR EACH ROW EXECUTE FUNCTION mail_retention_settings_stamp();

-- Deterministic expiry of one stored copy (docs/communications-e1.md §4). NULL = never automatically eligible.
--   ORDINARY:      the message's date + the business's ordinary period in force (no period, no expiry).
--   STAGED_INTAKE: when it was stored + 30 days (approved D-C2-6).
--   RETAINED_RECORD: no duration until an owner/legal decision sets one per record category (D-E1-5).
--   PERSONAL_UNSHARED: 30 days after departure or disconnect, which needs the copy's mailbox (C2-B2).
CREATE FUNCTION mail_retention_due_at(p_category text, p_occurred_at timestamptz, p_recorded_at timestamptz, p_ordinary_days integer)
RETURNS timestamptz LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path = pg_catalog AS $$
  SELECT CASE p_category
    WHEN 'ORDINARY' THEN p_occurred_at + make_interval(days => p_ordinary_days)
    WHEN 'STAGED_INTAKE' THEN p_recorded_at + interval '30 days'
    ELSE NULL
  END
$$;

-- ---- legal holds -----------------------------------------------------------------------------------
ALTER TABLE "communications_legal_holds"
  ADD CONSTRAINT communications_legal_holds_scope_values CHECK ("scope" IN ('BUSINESS', 'CONTACT', 'CONNECTION')),
  ADD CONSTRAINT communications_legal_holds_scope_target CHECK (
    ("scope" = 'BUSINESS' AND "contact_id" IS NULL AND "connection_id" IS NULL)
    OR ("scope" = 'CONTACT' AND "contact_id" IS NOT NULL AND "connection_id" IS NULL)
    OR ("scope" = 'CONNECTION' AND "connection_id" IS NOT NULL AND "contact_id" IS NULL)),
  ADD CONSTRAINT communications_legal_holds_reason_values CHECK ("reason_code" IN ('LITIGATION', 'REGULATORY', 'INVESTIGATION', 'OTHER')),
  ADD CONSTRAINT communications_legal_holds_release_pair CHECK (("released_at" IS NULL) = ("released_by_id" IS NULL));
-- At most one active hold per target; placing it again is idempotent in the service.
CREATE UNIQUE INDEX "communications_legal_holds_active_key" ON "communications_legal_holds"
  ("business_id", "scope", coalesce("contact_id", "connection_id", '00000000-0000-0000-0000-000000000000'::uuid)) WHERE "released_at" IS NULL;

-- Placing a hold takes the business's hold lock EXCLUSIVELY; every erasure step and purge batch holds it
-- SHARED for its whole transaction. So a hold either commits before an erasure starts (and is seen by it) or
-- waits for the erasure in progress to finish: there is no window in which a held copy is erased (§9).
CREATE FUNCTION communications_legal_holds_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtext('communications.legal_hold'), hashtext(NEW.business_id::text));
    IF NEW.released_at IS NOT NULL OR NEW.released_by_id IS NOT NULL THEN
      RAISE EXCEPTION 'a hold is placed active' USING ERRCODE = 'CM012';
    END IF;
    NEW.placed_at := now();
    RETURN NEW;
  END IF;
  IF current_user <> 'bos_maint'
     OR (NEW.id, NEW.business_id, NEW.scope, NEW.contact_id, NEW.connection_id, NEW.reason_code, NEW.placed_by_id, NEW.placed_at)
        IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.scope, OLD.contact_id, OLD.connection_id, OLD.reason_code, OLD.placed_by_id, OLD.placed_at)
     OR OLD.released_at IS NOT NULL OR NEW.released_by_id IS NULL THEN
    RAISE EXCEPTION 'a hold is released only through the privileged path, once' USING ERRCODE = 'CM012';
  END IF;
  NEW.released_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER communications_legal_holds_guard BEFORE INSERT OR UPDATE ON "communications_legal_holds"
  FOR EACH ROW EXECUTE FUNCTION communications_legal_holds_guard();

-- Is this stored copy under an active hold? Business-wide, or a hold on a contact that is the conversation's
-- contact or one of the copy's participants. (CONNECTION holds match once C2-B2 links copies to mailboxes.)
CREATE FUNCTION communications_message_held(p_business_id uuid, p_message_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
  SELECT EXISTS (
    SELECT 1 FROM "communications_legal_holds" h
     WHERE h."business_id" = p_business_id AND h."released_at" IS NULL
       -- CONNECTION: until C2-B3 records which mailbox a copy came from, a mailbox hold protects everything
       -- in the business (fail-safe: over-protect rather than miss a held copy).
       AND (h."scope" IN ('BUSINESS', 'CONNECTION')
            OR (h."scope" = 'CONTACT' AND (
                  EXISTS (SELECT 1 FROM "messages" m JOIN "conversations" c ON c."business_id" = m."business_id" AND c."id" = m."conversation_id"
                           WHERE m."business_id" = p_business_id AND m."id" = p_message_id AND c."contact_id" = h."contact_id")
               OR EXISTS (SELECT 1 FROM "message_participants" p
                           WHERE p."business_id" = p_business_id AND p."message_id" = p_message_id AND p."contact_id" = h."contact_id")))))
$$;
CREATE FUNCTION communications_contact_held(p_business_id uuid, p_contact_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
  SELECT EXISTS (
    SELECT 1 FROM "communications_legal_holds" h
     WHERE h."business_id" = p_business_id AND h."released_at" IS NULL
       AND (h."scope" IN ('BUSINESS', 'CONNECTION') OR (h."scope" = 'CONTACT' AND h."contact_id" = p_contact_id)))
$$;

-- ---- erasure ledger ---------------------------------------------------------------------------------
ALTER TABLE "communications_erasures"
  ADD CONSTRAINT communications_erasures_kind_values CHECK ("kind" IN ('REQUEST', 'RETENTION')),
  ADD CONSTRAINT communications_erasures_target_values CHECK ("target_type" IS NULL OR "target_type" IN ('CONTACT', 'CONVERSATION', 'MESSAGE')),
  ADD CONSTRAINT communications_erasures_shape CHECK (
    ("kind" = 'REQUEST' AND "requested_by_id" IS NOT NULL AND "reason_code" IN ('DATA_SUBJECT_REQUEST', 'BUSINESS_REQUEST', 'LEGAL_OBLIGATION') AND (
        ("target_type" = 'CONTACT' AND "contact_id" IS NOT NULL AND "conversation_id" IS NULL AND "message_id" IS NULL)
     OR ("target_type" = 'CONVERSATION' AND "conversation_id" IS NOT NULL AND "contact_id" IS NULL AND "message_id" IS NULL)
     OR ("target_type" = 'MESSAGE' AND "message_id" IS NOT NULL AND "contact_id" IS NULL AND "conversation_id" IS NULL)))
    OR ("kind" = 'RETENTION' AND "requested_by_id" IS NULL AND "reason_code" = 'RETENTION_EXPIRED' AND "target_type" IS NULL
        AND "contact_id" IS NULL AND "conversation_id" IS NULL AND "message_id" IS NULL AND "status" = 'COMPLETED')),
  ADD CONSTRAINT communications_erasures_status_values CHECK ("status" IN ('PENDING', 'DEFERRED', 'COMPLETED')),
  ADD CONSTRAINT communications_erasures_deferred CHECK (("status" = 'DEFERRED') = ("deferred_reason" IS NOT NULL)),
  ADD CONSTRAINT communications_erasures_deferred_values CHECK ("deferred_reason" IS NULL OR "deferred_reason" IN ('LEGAL_HOLD', 'RETAINED_RECORD')),
  ADD CONSTRAINT communications_erasures_completed CHECK (("status" = 'COMPLETED') = ("completed_at" IS NOT NULL)),
  ADD CONSTRAINT communications_erasures_counts CHECK (
    "attempts" >= 0 AND "messages_erased" >= 0 AND "participants_erased" >= 0 AND "activities_erased" >= 0
    AND "conversations_erased" >= 0 AND "review_required" >= 0 AND "deferred_count" >= 0),
  ADD CONSTRAINT communications_erasures_error_code CHECK ("last_error_code" IS NULL OR "last_error_code" ~ '^[a-z][a-z_]{0,63}$');
-- One open request per target: a repeated request returns the open one (idempotent).
CREATE UNIQUE INDEX "communications_erasures_open_target_key" ON "communications_erasures"
  ("business_id", "target_type", coalesce("contact_id", "conversation_id", "message_id")) WHERE "kind" = 'REQUEST' AND "status" <> 'COMPLETED';

ALTER TABLE "communications_erasure_items"
  ADD CONSTRAINT communications_erasure_items_entity_values CHECK ("entity_type" IN ('MESSAGE', 'PARTICIPANT', 'ACTIVITY', 'CONVERSATION')),
  ADD CONSTRAINT communications_erasure_items_action_values CHECK ("action" IN ('ERASED', 'REVIEW_REQUIRED'));

CREATE FUNCTION communications_erasures_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF (NEW.id, NEW.business_id, NEW.kind, NEW.target_type, NEW.contact_id, NEW.conversation_id, NEW.message_id, NEW.reason_code,
      NEW.requested_by_id, NEW.requested_at)
     IS DISTINCT FROM
     (OLD.id, OLD.business_id, OLD.kind, OLD.target_type, OLD.contact_id, OLD.conversation_id, OLD.message_id, OLD.reason_code,
      OLD.requested_by_id, OLD.requested_at)
     OR OLD.status = 'COMPLETED' THEN
    RAISE EXCEPTION 'erasure ledger entries are fixed' USING ERRCODE = 'CM013';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER communications_erasures_guard_update BEFORE UPDATE ON "communications_erasures"
  FOR EACH ROW EXECUTE FUNCTION communications_erasures_guard_update();
CREATE FUNCTION communications_erasure_append_only() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  RAISE EXCEPTION 'the erasure ledger is append-only' USING ERRCODE = 'CM013';
END $$;
CREATE TRIGGER communications_erasure_items_append_only BEFORE UPDATE ON "communications_erasure_items"
  FOR EACH ROW EXECUTE FUNCTION communications_erasure_append_only();

-- ---- keyed erased references, keys and privileged grants (bos_maint only) ----------------------------
ALTER TABLE "communications_erased_references"
  ADD CONSTRAINT communications_erased_references_kind_values CHECK ("kind" IN ('MESSAGE', 'THREAD')),
  ADD CONSTRAINT communications_erased_references_digest_format CHECK ("digest" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT communications_erased_references_expiry CHECK ("expires_at" > "created_at");
ALTER TABLE "communications_erasure_keys"
  ADD CONSTRAINT communications_erasure_keys_length CHECK (octet_length("secret") = 32);
ALTER TABLE "communications_privileged_grants"
  ADD CONSTRAINT communications_privileged_grants_operation_values CHECK ("operation" IN (
    'ERASE_CONTACT', 'ERASE_CONVERSATION', 'ERASE_MESSAGE', 'RELEASE_LEGAL_HOLD', 'APPLY_RETENTION_REDUCTION')),
  ADD CONSTRAINT communications_privileged_grants_code_format CHECK ("code_hash" ~ '^[0-9a-f]{64}$'),
  -- Short-lived: at most 10 minutes (5 used).
  ADD CONSTRAINT communications_privileged_grants_lifetime CHECK ("expires_at" > "created_at" AND "expires_at" <= "created_at" + interval '10 minutes');

-- ---- audit: erasure events are written only by the privileged path ----------------------------------
-- bos_app could otherwise forge "communications.erasure.*" evidence by choosing app.user_id. RESTRICTIVE, so
-- it narrows every existing bos_app INSERT policy (audit_tenant_write and audit_system_write).
CREATE POLICY audit_no_app_erasure_events ON "audit_events" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("action" NOT LIKE 'communications.erasure.%');

-- ---- least privilege -----------------------------------------------------------------------------------
-- The existing table grants of the C1 tables are left exactly as they were (no new UPDATE or DELETE right for
-- bos_app). What the application may not write on INSERT is refused by triggers instead: erased_at on every
-- table (an erased row is only ever produced by the bos_maint tombstone), and retention_category, which only the
-- C2-B3 sync writer will set (its role and rules come with C2-B3; until then no runtime role can categorise).
CREATE FUNCTION communications_insert_not_erased() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF NEW.erased_at IS NOT NULL THEN
    RAISE EXCEPTION 'a row cannot be recorded as erased' USING ERRCODE = 'CM011';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER conversations_insert_not_erased BEFORE INSERT ON "conversations" FOR EACH ROW EXECUTE FUNCTION communications_insert_not_erased();
CREATE TRIGGER activities_insert_not_erased BEFORE INSERT ON "activities" FOR EACH ROW EXECUTE FUNCTION communications_insert_not_erased();
REVOKE ALL ON FUNCTION communications_insert_not_erased() FROM PUBLIC;

-- The six new tables: drop the default privileges bos_owner's tables get (docker/init/01-roles.sql grants
-- SELECT, INSERT, UPDATE, DELETE to bos_app), then grant only what the application needs. Keys, markers and
-- single-use codes: nothing at all (only the bos_maint functions touch them).
REVOKE ALL ON "communications_erasures", "communications_erasure_items", "communications_legal_holds", "communications_erasure_keys",
  "communications_erased_references", "communications_privileged_grants" FROM bos_app;
GRANT SELECT ON "communications_erasures", "communications_erasure_items", "communications_legal_holds" TO bos_app;
GRANT INSERT ("id", "business_id", "scope", "contact_id", "connection_id", "reason_code", "placed_by_id", "placed_at")
  ON "communications_legal_holds" TO bos_app;

REVOKE ALL ON FUNCTION mail_effective_ordinary_days(integer, integer, timestamptz), mail_retention_due_at(text, timestamptz, timestamptz, integer),
  communications_message_held(uuid, uuid), communications_contact_held(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mail_effective_ordinary_days(integer, integer, timestamptz), mail_retention_due_at(text, timestamptz, timestamptz, integer),
  communications_message_held(uuid, uuid), communications_contact_held(uuid, uuid) TO bos_app;
REVOKE ALL ON FUNCTION messages_guard_insert(), message_participants_guard_insert(), mail_retention_settings_stamp(),
  communications_legal_holds_guard(), communications_erasures_guard_update(), communications_erasure_append_only() FROM PUBLIC;

-- ---- row-level security --------------------------------------------------------------------------
ALTER TABLE "communications_erasures" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "communications_erasures" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "communications_erasures" FOR SELECT TO bos_app
  USING ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "communications_erasure_items" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "communications_erasure_items" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "communications_erasure_items" FOR SELECT TO bos_app
  USING ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "communications_legal_holds" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "communications_legal_holds" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "communications_legal_holds" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY placed_by_session_user ON "communications_legal_holds" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("placed_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);

-- Keys, references and grants: RLS forced and no bos_app policy at all, so the application sees nothing.
ALTER TABLE "communications_erasure_keys" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "communications_erasure_keys" FORCE ROW LEVEL SECURITY;
ALTER TABLE "communications_erased_references" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "communications_erased_references" FORCE ROW LEVEL SECURITY;
ALTER TABLE "communications_privileged_grants" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "communications_privileged_grants" FORCE ROW LEVEL SECURITY;

COMMIT;
